-- V-023 (run O1, session.sh G and J4): after 023-dle-otakudle.sql
-- Read only, in a read-only transaction. Each row is: ok or KO | what | the number found. Never a name, an e-mail or a row of a person.
-- From the header of 023-dle-otakudle.sql. The game row comes with L01's anime site (J4): before it the row must be absent, after it there; off until L14, and whole after it.
begin transaction read only;
select case when ok is true then 'ok' else 'KO' end, what, coalesce(got, '-') from (values
  (1, 'character_facts et series_facts avec RLS, aucune policy', (select count(*) = 2 from pg_class c where c.oid in (to_regclass('public.character_facts'), to_regclass('public.series_facts')) and c.relrowsecurity and not exists (select 1 from pg_policy p where p.polrelid = c.oid)), null),
  (2, 'colonnes : character_facts 8 (dont featured, CR-023), series_facts 3', (select count(*) = 11 from information_schema.columns where table_schema = 'public' and ((table_name = 'character_facts' and column_name in ('character_id', 'gender', 'species', 'role_at_debut', 'first_appearance', 'voice_actor_ja', 'featured', 'updated_at')) or (table_name = 'series_facts' and column_name in ('group_id', 'demographic', 'updated_at')))), null),
  (3, 'les deux tables fermées à anon et authenticated, ouvertes au service_role', (select bool_and(not has_table_privilege('anon', t, 'select') and not has_table_privilege('authenticated', t, 'select') and not has_table_privilege('anon', t, 'insert') and not has_table_privilege('authenticated', t, 'insert') and has_table_privilege('service_role', t, 'select')) from (values ('public.character_facts'), ('public.series_facts')) as x(t)), null),
  (4, 'vue dle_src_anime_character en security_invoker, fermée au navigateur', (select coalesce('security_invoker=true' = any (reloptions), false) and not has_table_privilege('anon', oid, 'select') and not has_table_privilege('authenticated', oid, 'select') from pg_class where oid = to_regclass('public.dle_src_anime_character')), null),
  (5, 'la vue garde la règle : publié seulement, aucun filtre de spoiler (CR-023)', (select d ~ 'published' and d !~ 'spoiler_level = 0' and d !~ '(?i)not c.identity_spoiler' from pg_get_viewdef('public.dle_src_anime_character'::regclass) as d), null),
  (6, 'la vue lit le studio de la saison 1, sinon celui de la série', (select pg_get_viewdef('public.dle_src_anime_character'::regclass) ~ '@> ''\[1\]''::jsonb' and pg_get_viewdef('public.dle_src_anime_character'::regclass) ~ 'anime_original'), null),
  (7, 'otakudle : là si le site anime est là, absent avant L01', (select exists (select 1 from public.dle_games where id = 'otakudle') = exists (select 1 from public.sites where id = 'anime')), (select count(*)::text from public.dle_games where id = 'otakudle')),
  (8, 'otakudle : éteint sans date ni banque, ou allumé par L14 avec ses 365 jours', (select coalesce(bool_and((not g.active and g.epoch is null and not exists (select 1 from public.dle_schedule s where s.game_id = g.id)) or (g.active and g.epoch is not null and (select count(*) from public.dle_schedule s where s.game_id = g.id) = 365)), true) from public.dle_games g where g.id = 'otakudle'), null),
  (9, 'otakudle : 7 colonnes si le jeu est là', (select (select count(*) from public.dle_attributes where game_id = 'otakudle') = case when exists (select 1 from public.dle_games where id = 'otakudle') then 7 else 0 end), (select count(*)::text from public.dle_attributes where game_id = 'otakudle')),
  (10, 'otakudle : indices après 5 et 10 erreurs (doubleur japonais, initiale)', (select coalesce(bool_and(hint_keys = '{voice_actor_ja,initial}' and hint_after = '{5,10}'), true) from public.dle_games where id = 'otakudle'), null),
  (11, 'personnages dans la vue (information)', true, (select count(*)::text from public.dle_src_anime_character)),
  (12, 'la vue : une cible est du TOP200 (featured) et a son doubleur japonais (CR-023)', (select d ~ 'featured' and d ~ 'voice_actor_ja IS NOT NULL' from pg_get_viewdef('public.dle_src_anime_character'::regclass) as d), null),
  (13, 'la vue n''a aucune règle de progression : ni seen_anime, seen_manga, seen_beginner, ni seen_at (CR-026)', (select d !~ 'seen_' from pg_get_viewdef('public.dle_src_anime_character'::regclass) as d), null)
) as c(n, what, ok, got) order by n;
rollback;
